import { 
  MeshBasicNodeMaterial, 
  PlaneGeometry,
  DoubleSide
} from 'three/webgpu';
import { 
  texture, 
  uv, 
  vec3, 
  mix, 
  smoothstep, 
  uniform 
} from 'three/tsl';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const { Group, Mesh, Vector3 } = ctx.THREE;
  const group = new Group();

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: "#16161d",
    paper: "#e8ecf2",
    accent: "#ff2a38",
    surface: "#0b0b10"
  };

  const inkColor = new ctx.THREE.Color(colors.ink);
  const paperColor = new ctx.THREE.Color(colors.paper);
  const accentColor = new ctx.THREE.Color(colors.accent);
  const surfaceColor = new ctx.THREE.Color(colors.surface);

  // --- STAGE BACKDROP ---
  // Create a subtle vertical gradient backdrop representing an "engineered gradient surface"
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial({ side: DoubleSide });

  // TSL Gradient nodes
  const vUv = uv();
  const gradMix = smoothstep(0.0, 1.0, vUv.y);
  const backgroundNode = mix(vec3(surfaceColor.r, surfaceColor.g, surfaceColor.b), vec3(inkColor.r, inkColor.g, inkColor.b), gradMix);
  backdropMat.colorNode = backgroundNode;

  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);

  // --- CARD & IMAGE PORTION ---
  // Create card panel
  const cardGeo = new PlaneGeometry(2.4, 1.8);
  const cardMat = new MeshBasicNodeMaterial({ transparent: true, side: DoubleSide });

  // Base card styling
  const cardBaseColor = vec3(surfaceColor.r, surfaceColor.g, surfaceColor.b);
  cardMat.colorNode = cardBaseColor;

  const cardMesh = new Mesh(cardGeo, cardMat);
  cardMesh.position.set(0, 0.2, 0);
  group.add(cardMesh);

  // Load the specified orb-decor asset if provided
  const imageUrl = config.imageUrl ?? "/prism-mock/home/nodes/orb-decor.png";
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      tex.colorSpace = ctx.THREE.SRGBColorSpace;
      const overlayGeo = new PlaneGeometry(2.2, 1.2);
      const overlayMat = new MeshBasicNodeMaterial({
        map: tex,
        transparent: true,
        side: DoubleSide
      });
      const overlayMesh = new Mesh(overlayGeo, overlayMat);
      overlayMesh.position.set(0, 0.4, 0.02);
      group.add(overlayMesh);
    }).catch(err => {
      console.warn("Failed to load orb-decor texture:", err);
    });
  }

  // --- TEXT CONTENT ---
  // Default text config fallback using bridging idiom
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  let headlineString = "Features 2";

  for (const item of textItems) {
    if (typeof item === 'string') {
      headlineString = item;
    } else if (item && typeof item === 'object' && item.text) {
      headlineString = item.text;
    }
  }

  // Draw headline (39px ~ 0.22 display height contextually)
  const headline = ctx.fontAtlas.createText(headlineString, {
    fontSize: 0.22,
    color: colors.paper,
    align: 'center'
  });
  headline.position.set(0, -0.4, 0.05);
  group.add(headline);

  // Draw secondary accent line signaling architectural details
  const lineGeo = new PlaneGeometry(2.0, 0.02);
  const lineMat = new MeshBasicNodeMaterial({
    color: colors.accent,
    transparent: true,
    opacity: 0.8
  });
  const lineMesh = new Mesh(lineGeo, lineMat);
  lineMesh.position.set(0, -0.65, 0.05);
  group.add(lineMesh);

  // --- ENTRANCE ANIMATION ---
  // Weighted rise-in / fade-up style movement using valid GSAP
  group.position.y += 0.3;
  group.scale.set(0.95, 0.95, 0.95);

  const entranceTl = gsap.timeline();
  entranceTl.to(group.position, {
    y: 0,
    duration: 0.85,
    ease: "power3.out"
  });
  entranceTl.to(group.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: "power4.out"
  }, 0);

  // --- CLEANUP ---
  group.userData = {
    handlers: {},
    cleanup: () => {
      if (entranceTl) entranceTl.kill();
      backdropGeo.dispose();
      backdropMat.dispose();
      cardGeo.dispose();
      cardMat.dispose();
      lineGeo.dispose();
      lineMat.dispose();
    }
  };

  return group;
}
